package net.civeira.phylax.feature.access.usermfaenrollment.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.crypto.KeyRingSecretStorage;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.usermfaenrollment.domain.UserMfaEnrollment;
import net.civeira.phylax.feature.access.usermfaenrollment.domain.valueobject.PendingSeedVO;

@RequiredArgsConstructor
public class PendingSeedValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<PendingSeedVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param service
   * @param owner Entity uid
   * @return
   */
  public Optional<String> getPendingSeedStored(KeyRingSecretStorage service, String owner) {
    return value.flatMap(val -> val.getPendingSeedStored(service, owner));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<PendingSeedVO> getPendingSeedValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param pendingSeed
   * @return
   */
  public T pendingSeed(PendingSeedVO pendingSeed) {
    this.value = Optional.of(pendingSeed);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param pendingSeed
   * @return
   */
  public T pendingSeed(Optional<PendingSeedVO> pendingSeed) {
    this.value = pendingSeed;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T pendingSeedNull() {
    this.value = Optional.of(PendingSeedVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param pendingSeed
   * @return
   */
  public T pendingSeedPlain(String pendingSeed) {
    this.value = Optional.of(PendingSeedVO.fromPlain(pendingSeed));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param pendingSeed
   * @return
   */
  public T pendingSeedStored(String pendingSeed) {
    this.value = Optional.of(PendingSeedVO.fromStored(pendingSeed));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public PendingSeedVO readPendingSeed(final Optional<UserMfaEnrollment> original,
      final ConstraintFailList fails) {
    return value.orElse(
        original.map(UserMfaEnrollment::getPendingSeedValue).orElseGet(PendingSeedVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetPendingSeed() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetPendingSeedIfMatches(final String field) {
    if ("pendingSeed".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
